package com.example.starter.fishery.domain;

/**
 * 渔船航次状态，流转：DEPARTED（出港申报受理）→ DISCHARGED（进港报告完成）→ CLOSED（配额核销结案）；
 * 进港偏差或兼捕触发人工复核时为 IN_REVIEW，复核结论后回到 DISCHARGED。
 */
public enum TripStatus {
    /** 出港申报已受理，作业中。 */
    DEPARTED,
    /** 进港报告已提交，等待配额核销（无未决复核）。 */
    DISCHARGED,
    /** 人工复核中，该船配额余额冻结。 */
    IN_REVIEW,
    /** 终态：配额核销完成，航次结案。 */
    CLOSED
}

package com.example.starter.fishery.domain;

/**
 * 复核案件状态。
 */
public enum ReviewStatus {
    /** 待人工复核（审查队列）。 */
    OPEN,
    /** 复核结论已作出，为最终口径。 */
    CLOSED
}

package com.example.starter.fishery.domain;

/**
 * 触发人工复核的原因。
 */
public enum ReviewReason {
    /** 兼捕保护鱼种占比超过 5%。 */
    BYCATCH_RATIO,
    /** 进港卸渔量与日志累计量偏差超过 3%。 */
    LANDING_DEVIATION,
    /** 结案后迟到日志。 */
    LATE_LOG
}

package com.example.starter.fishery.domain;

/**
 * 人工复核最终口径。
 */
public enum ReviewConclusion {
    /** 以进港卸渔量为准。 */
    CONFIRM_LANDED,
    /** 以日志累计量为准。 */
    CONFIRM_LOGGED,
    /** 复核员给出调整后数量。 */
    ADJUSTED
}

package com.example.starter.fishery.api;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * 业务规则拒绝（如配额超限整笔拒绝、状态不允许、差异说明缺失），映射 422。
 */
@ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
public class BusinessRuleException extends RuntimeException {

    public BusinessRuleException(String message) {
        super(message);
    }
}

package com.example.starter.fishery.api;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * 冲突错误（同键异参、重复受理、并发余额不足等），映射 409。
 */
@ResponseStatus(HttpStatus.CONFLICT)
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.fishery.api;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/**
 * 资源不存在，映射 404。
 */
@ResponseStatus(HttpStatus.NOT_FOUND)
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

