package com.example.starter.fishery.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.DecimalMin;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 出港申报请求。
 *
 * @param requestId 幂等键
 * @param tripCode 航次业务编号（全库唯一）
 * @param vesselCode 渔船编号
 * @param departAt 出港时刻（UTC，ISO-8601）
 * @param lines 分鱼种申报捕捞量（千克）
 */
public record DepartureRequest(
        @NotBlank String requestId,
        @NotBlank String tripCode,
        @NotBlank String vesselCode,
        @NotNull Instant departAt,
        @NotEmpty @Valid List<SpeciesWeight> lines) {

    /** 鱼种数量行。 */
    public record SpeciesWeight(
            @NotBlank String speciesCode,
            @NotNull @DecimalMin(value = "0.001", message = "数量必须大于0") BigDecimal weightKg) {
    }
}

package com.example.starter.fishery.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 渔捞日志提交请求；按作业时刻（UTC）归属日界，按“船＋日期＋渔区”去重。
 *
 * @param requestId 幂等键
 * @param tripCode 航次业务编号
 * @param zoneCode 渔区编号
 * @param fishingAt 作业时刻（UTC，ISO-8601）
 * @param lines 分鱼种渔获量（千克）
 */
public record LogbookRequest(
        @NotBlank String requestId,
        @NotBlank String tripCode,
        @NotBlank String zoneCode,
        @NotNull Instant fishingAt,
        @NotEmpty @Valid List<SpeciesLine> lines) {

    /** 分鱼种渔获行。 */
    public record SpeciesLine(
            @NotBlank String speciesCode,
            @NotNull @DecimalMin(value = "0.001", message = "数量必须大于0") BigDecimal weightKg) {
    }
}

package com.example.starter.fishery.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 进港报告（卸渔）请求。
 *
 * @param requestId 幂等键
 * @param tripCode 航次业务编号
 * @param landedAt 进港时刻（UTC，ISO-8601）
 * @param lines 分鱼种卸渔量（千克）
 * @param deviationExplanation 卸渔量与日志累计量偏差超过 3% 时必填的差异说明
 */
public record LandingRequest(
        @NotBlank String requestId,
        @NotBlank String tripCode,
        @NotNull Instant landedAt,
        @NotEmpty @Valid List<SpeciesLine> lines,
        String deviationExplanation) {

    /** 分鱼种卸渔行。 */
    public record SpeciesLine(
            @NotBlank String speciesCode,
            @NotNull BigDecimal weightKg) {
    }
}

